function loc(){return state.data?.locale||'ru'} function t(){return locales[loc()]||locales.ru} function statusIndex(s){s=(s||'').toUpperCase();return s==='PAYMENT_PENDING'?2:(s==='PAID'||s==='BOOKING_CONFIRMED')?3:(s==='DOCUMENTS_READY'||s==='READY_TO_TRAVEL')?4:s==='IN_TRIP'?5:s==='COMPLETED'?6:1} function statusColor(s){s=(s||'').toUpperCase();return s==='PAYMENT_PENDING'?'var(--orange)':(s==='PAID'||s==='BOOKING_CONFIRMED')?'var(--green)':(s==='DOCUMENTS_READY'||s==='READY_TO_TRAVEL')?'var(--teal)':s==='IN_TRIP'?'var(--blue)':s==='COMPLETED'?'var(--indigo)':s==='CANCELLED'?'var(--red)':'var(--yellow)'} function nodeFG(s){s=(s||'').toUpperCase();return (s==='NEW'||s==='AVAILABILITY_CHECK')?'rgba(0,0,0,.78)':'#fff'}
